export const loadModelOptionsToRequestSchema = misplacedLoadModelConfigGuard.pipe(loadModelOptionsToRequestBaseSchema);
const commonModelConfigSchema = z.object({
    type: z.literal('loadModel'),
    modelSrc: z.string().describe(MODEL_SRC_DESCRIPTION),
    modelName: z.string().optional(),
    withProgress: z.boolean().optional(),
    seed: z.boolean().optional(),
    fallbackSrc: z
        .string()
        .optional()
        .describe('Alternate source — an HTTP URL or local file path — used to load a built-in registry model when it cannot be downloaded from the registry. The bytes are validated against the model checksum before use.'),
    requireHttpChecksum: z
        .boolean()
        .optional()
        .describe('Reject a Hugging Face HTTP download that exposes no usable SHA-256 instead of downloading it unverified. Overrides the engine config for this call; defaults to the config value (false).'),
    requireSecureTransport: z
        .boolean()
        .optional()
        .describe('Reject plaintext http:// and HTTPS→HTTP downgrades for every HTTP source on this call (loopback exempt); when unset, only Hugging Face transport is hardened. Overrides the engine config for this call; defaults to the config value (false).'),
    requestId: z
        .string()
        .min(1)
        .optional()
        .describe('Stable identifier for this in-flight load, generated by the client at call time. Optional on the wire so legacy clients keep working — the server falls back to a server-generated id when the field is missing. Exposed on the client-side decorated promise so callers can target this load with `cancel({ requestId })`.')
});
// Request schemas for each model type (use canonical types since transforms normalize)
// Use base schemas (no defaults) for client-side validation.
// Server applies device defaults, then full schema defaults.
export const loadLlmModelRequestSchema = commonModelConfigSchema
    .extend({
    modelType: z.literal(ModelType.llamacppCompletion),
    modelConfig: llmConfigBaseSchema
})
    .strict();
